ALTER TYPE "DeliveryMethod" ADD VALUE IF NOT EXISTS 'YANDEX_STANDARD';
UPDATE "Product" SET "isPreorder" = false, "preorderShipAt" = NULL WHERE "isPreorder" OR "preorderShipAt" IS NOT NULL;

UPDATE "ReplyTemplate" SET "text" = 'Доставляем через СДЭК, Яндекс Доставку и Яндекс Экспресс.' WHERE "shortcut" = '/доставка' AND "text" = 'Доставляем курьером по Москве и Петербургу с примеркой за 1–2 дня, по России — СДЭК 2–7 дней. Бесплатно от 15 000 ₽.';

UPDATE "ReplyTemplate" SET "text" = '{имя}, для оформления возврата напишите нам номер заказа и название вещи. Обратиться можно в течение 14 дней с момента получения. Сохраните ярлыки и товарный вид вещи.' WHERE "shortcut" = '/возврат' AND "text" = '{имя}, вернуть вещь можно в течение 14 дней после получения, если сохранены ярлыки. Оформите возврат в личном кабинете или пришлите номер заказа — я всё сделаю за вас. Деньги вернутся в течение 10 дней.';

UPDATE "ReplyTemplate" SET "text" = 'Подскажите, пожалуйста, по какой вещи нужна консультация стилиста?' WHERE "shortcut" = '/стилист' AND "text" = 'Запишу вас к стилисту в шоурум на Большой Никитской или на примерку дома. Какие дата и время удобны?';

UPDATE "Campaign" SET "text" = replace("text", 'В Москве и Петербурге вещи можно примерить дома: курьер привозит заказ, ждёт до двадцати минут, вы оставляете только то, что сидит. Обмен и возврат — четырнадцать дней.', 'Доставляем заказы через СДЭК, Яндекс Доставку и Яндекс Экспресс. Для возврата обратитесь в поддержку в течение 14 дней с момента получения.') WHERE "status" IN ('DRAFT', 'SCHEDULED') AND strpos("text", 'В Москве и Петербурге вещи можно примерить дома: курьер привозит заказ, ждёт до двадцати минут, вы оставляете только то, что сидит. Обмен и возврат — четырнадцать дней.') > 0;

UPDATE "Campaign" SET "text" = replace("text", 'При оформлении заказа отметьте «Примерка курьером». В Москве и Петербурге курьер привезёт вещи в удобный интервал и подождёт до двадцати минут. Можно заказать два размера одной вещи и оставить один — за второй деньги не списываются.', 'Сверьте свои мерки с таблицей размеров в карточке вещи.') WHERE "status" IN ('DRAFT', 'SCHEDULED') AND strpos("text", 'При оформлении заказа отметьте «Примерка курьером». В Москве и Петербурге курьер привезёт вещи в удобный интервал и подождёт до двадцати минут. Можно заказать два размера одной вещи и оставить один — за второй деньги не списываются.') > 0;

UPDATE "Campaign" SET "name" = replace("name", 'Как устроена примерка дома (письмо 2)', 'Как выбрать размер (письмо 2)') WHERE "status" IN ('DRAFT', 'SCHEDULED') AND strpos("name", 'Как устроена примерка дома (письмо 2)') > 0;

UPDATE "Campaign" SET "subject" = replace("subject", 'Примерка дома: два размера, один курьер', 'Как выбрать свой размер') WHERE "status" IN ('DRAFT', 'SCHEDULED') AND strpos("subject", 'Примерка дома: два размера, один курьер') > 0;
